import { describe, it, expect, vi } from 'vitest'
import { middleware } from './middleware'
import { NextRequest } from 'next/server'

describe('Middleware', () => {
  it('should add X-Request-Id header and log pathname', () => {
    const request = new NextRequest('http://localhost/test-path')
    const consoleSpy = vi.spyOn(console, 'log')

    const response = middleware(request)

    const requestId = response.headers.get('X-Request-Id')
    expect(requestId).toBeDefined()
    expect(requestId?.length).toBeGreaterThan(0)

    // Check if the log was called with the correct pathname
    // The exact log message format in middleware.ts is: "Request Pathname: ${request.nextUrl.pathname}"
    expect(consoleSpy).toHaveBeenCalledWith(expect.stringContaining('Request Pathname: /test-path'))
  })
})

